-- Frozen G1 business schema V1. Synthetic migration fixture only.
PRAGMA foreign_keys=ON;
CREATE TABLE work_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE binding_heads(bot_id TEXT PRIMARY KEY,agent_id TEXT NOT NULL,binding_id TEXT NOT NULL,version INTEGER NOT NULL,project_id TEXT NOT NULL,policy_version INTEGER NOT NULL,identity_digest TEXT NOT NULL,active INTEGER NOT NULL CHECK(active IN(0,1)));
CREATE UNIQUE INDEX active_work_agent ON binding_heads(agent_id) WHERE active=1;
CREATE TABLE work_sessions(id TEXT PRIMARY KEY,scope_key TEXT NOT NULL UNIQUE,scope_json TEXT NOT NULL);
CREATE TABLE work_tasks(id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES work_sessions(id),scope_key TEXT NOT NULL,bot_id TEXT NOT NULL,number INTEGER NOT NULL CHECK(number>0),kind TEXT NOT NULL CHECK(kind IN('work','chat')),goal TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('queued','held','dispatching','running','waiting_input','waiting_approval','cancelling','reconciling','unknown','succeeded','failed','cancelled')),current_run_id TEXT REFERENCES work_runs(id),created_at TEXT NOT NULL,UNIQUE(bot_id,number),UNIQUE(id,scope_key));
CREATE TABLE work_inbox(bot_id TEXT NOT NULL,event_id TEXT NOT NULL,scope_key TEXT NOT NULL,task_id TEXT NOT NULL REFERENCES work_tasks(id),PRIMARY KEY(bot_id,event_id));
CREATE TABLE work_runs(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES work_tasks(id),scope_key TEXT NOT NULL,attempt INTEGER NOT NULL CHECK(attempt>0),state TEXT NOT NULL CHECK(state IN('dispatching','running','waiting_input','waiting_approval','cancelling','reconciling','unknown','succeeded','failed','cancelled')),dispatch_key TEXT NOT NULL UNIQUE,external_ref TEXT,last_seq INTEGER NOT NULL DEFAULT 0 CHECK(last_seq>=0),policy_version INTEGER NOT NULL CHECK(policy_version>0),UNIQUE(task_id,attempt),UNIQUE(scope_key,external_ref),FOREIGN KEY(task_id,scope_key) REFERENCES work_tasks(id,scope_key));
CREATE TABLE work_events(run_id TEXT NOT NULL REFERENCES work_runs(id),event_id TEXT NOT NULL,seq INTEGER NOT NULL CHECK(seq>0),type TEXT NOT NULL,schema_version INTEGER NOT NULL CHECK(schema_version=1),occurred_at TEXT NOT NULL,received_at TEXT NOT NULL,correlation_id TEXT NOT NULL,data_json TEXT NOT NULL,event_digest TEXT NOT NULL,applied INTEGER NOT NULL CHECK(applied IN(0,1)),PRIMARY KEY(run_id,seq),UNIQUE(run_id,event_id));
CREATE TABLE work_actions(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES work_runs(id),scope_key TEXT NOT NULL,type TEXT NOT NULL,data_json TEXT NOT NULL);
CREATE TABLE work_outbox(id TEXT PRIMARY KEY,scope_key TEXT NOT NULL,run_id TEXT NOT NULL REFERENCES work_runs(id),body TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('queued','sending','sent','failed','frozen','unknown')),attempt_token TEXT,receipt_ref TEXT,UNIQUE(run_id));
